import{_ as t}from"./chunks/reactive-is-all-you-need.C1lVmqE8.js";import{_ as a,o,c as s,aa as i}from"./chunks/framework.vV0l90Ad.js";import"./chunks/theme.D160HLBh.js";const g=JSON.parse('{"title":"Reactive() is all you need","description":"Store libraries, composable factories, service layers, emitters, DI containers — the state-management zoo reduces to plain classes and one prototype transform. The roles were never different things; they were one thing with different lifetimes.","frontmatter":{"title":"Reactive() is all you need","description":"Store libraries, composable factories, service layers, emitters, DI containers — the state-management zoo reduces to plain classes and one prototype transform. The roles were never different things; they were one thing with different lifetimes.","date":"2026-07"},"headers":[],"relativePath":"blog/reactive-is-all-you-need.md","filePath":"blog/reactive-is-all-you-need.md","lastUpdated":1786399507000}'),n={name:"blog/reactive-is-all-you-need.md"};function r(c,e,l,d,h,m){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="reactive-is-all-you-need" tabindex="-1">Reactive() is all you need <a class="header-anchor" href="#reactive-is-all-you-need" aria-label="Permalink to &quot;Reactive() is all you need&quot;">​</a></h1><p><img src="'+t+'" alt="Reactive() is all you need"></p><p>The most influential machine-learning paper of the last decade is famous for its title before its math. <em>Attention Is All You Need</em> didn&#39;t claim attention was magic — it claimed the <strong>zoo was unnecessary</strong>: the recurrent networks, the convolutional encoders, the task-specific architectures bolted together per problem could all be replaced by one primitive, repeated.</p><p>Frontend state management has a zoo of its own. A mature Vue application typically carries a store library for shared state, a composable convention for reusable logic, a service layer for &quot;business logic,&quot; an event emitter for cross-module signals, and some flavor of dependency injection to wire it together. Five categories. Five APIs, five lifecycle stories, five sets of documentation, five ways a new team member can put code in the wrong place.</p><p>The claim of this post is the paper&#39;s claim: the zoo is unnecessary. Every one of those categories is the same three needs wearing different uniforms — <strong>state, derivations of state, and actions that mutate state</strong> — plus one honest variable: <em>how long the thing lives</em>.</p><h2 id="the-zoo-reduced" tabindex="-1">The zoo, reduced <a class="header-anchor" href="#the-zoo-reduced" aria-label="Permalink to &quot;The zoo, reduced&quot;">​</a></h2><p>Hold a <code>Reactive()</code> class against each category and watch the category dissolve:</p><table tabindex="0"><thead><tr><th>the category</th><th>what it actually is</th><th>as a Reactive class</th></tr></thead><tbody><tr><td>store</td><td>shared state + derivations + actions, app lifetime</td><td>a module-singleton instance</td></tr><tr><td>composable</td><td>state + derivations + actions, caller&#39;s lifetime</td><td>the same class, constructed where you need it</td></tr><tr><td>service</td><td>actions around injected dependencies</td><td>methods + <a href="/guide/modules#injecting-stores-and-composables-the-slot"><code>$</code>-getter injections</a></td></tr><tr><td>view-model</td><td>state + derivations bound to one component</td><td>the same class, constructed in <code>setup()</code></td></tr><tr><td>domain entity</td><td>state + derivations + actions, data lifetime</td><td>the same class, thousands of instances</td></tr></tbody></table><p>Five rows, one right-hand column. The categories were never different <em>kinds</em> of thing — they were one kind of thing at different <strong>lifetimes</strong>, and the ecosystem shipped a separate library for each lifetime because no primitive spanned them.</p><p><code>Reactive()</code> spans them. The constructor runs synchronously wherever you <code>new</code> — construct in <code>setup()</code> and plain <code>watch</code>/<code>onMounted</code> register against the component; construct at module scope and <a href="/guide/lifecycle-teardown"><code>$watch</code></a> registers in the instance&#39;s own detached scope, disposed by an owner calling <code>$stopEffects()</code>. Same class, both lifetimes, chosen at the call site — the one variable that was ever real is the one you control directly.</p><h2 id="what-each-library-was-compensating-for" tabindex="-1">What each library was compensating for <a class="header-anchor" href="#what-each-library-was-compensating-for" aria-label="Permalink to &quot;What each library was compensating for&quot;">​</a></h2><p>Each cage in the zoo exists because plain classes historically couldn&#39;t do the job:</p><ul><li><strong>Store libraries</strong> exist because sharing a reactive object across components needed framework blessing. A Reactive instance is a plain object with cached Refs — export it from a module and it is shared, no plugin, no <code>install()</code>.</li><li><strong>Composable factories</strong> exist because logic reuse needed a function scope to hold refs. A class holds them on the prototype pattern instead — with inheritance, <code>instanceof</code>, and <a href="/guide/modules">circular-import immunity</a> the closure never had.</li><li><strong>Service layers with DI</strong> exist because classes constructed eagerly couldn&#39;t safely touch stores at load time. The <code>$</code>-getter resolves dependencies on <strong>first access</strong>, after everything is installed — injection without a container.</li><li><strong>Event emitters</strong> exist to signal across modules without coupling. A watcher on a ref <em>is</em> that signal, with teardown owned by <a href="/guide/lifecycle-teardown"><code>$stopEffects()</code></a> instead of a manual <code>off()</code> bookkeeping ledger.</li></ul><p>None of these libraries was a mistake. Each was the correct patch for a missing primitive. The primitive stopped being missing.</p><h2 id="proof-by-existence" tabindex="-1">Proof by existence <a class="header-anchor" href="#proof-by-existence" aria-label="Permalink to &quot;Proof by existence&quot;">​</a></h2><p>This is not a thought experiment. <a href="https://github.com/infinite-system/invar" target="_blank" rel="noreferrer">Invar</a>, the terminal code editor <a href="/blog/agents-built-an-editor">built almost entirely by AI agents</a>, is 25,890 lines with <strong>no store library, no DI container, no emitter, no composable layer</strong>: 42 <code>Reactive()</code> classes cover every stateful role in the table above, 34 <a href="/guide/static"><code>Static()</code></a> seams cover the stateless capabilities, and the whole model layer underneath is <a href="/blog/one-kilobyte-feature">1.1 kB</a>. The <a href="/blog/twenty-million-cells">20,000,000-cell spreadsheet</a> runs the same way. So does every demo on this site.</p><h2 id="what-all-does-not-mean" tabindex="-1">What &quot;all&quot; does not mean <a class="header-anchor" href="#what-all-does-not-mean" aria-label="Permalink to &quot;What &quot;all&quot; does not mean&quot;">​</a></h2><p>A claim shaped like this one earns its keep by what it rules out, so here is the boundary, stated plainly:</p><ul><li><strong>Rendering is not ivue&#39;s job.</strong> Vue owns templates and the DOM; OpenTUI owns Invar&#39;s framebuffer. <code>Reactive()</code> is the model layer under a renderer, not a renderer.</li><li><strong>The static side has its own transform.</strong> Stateless capability classes — function bags behind a replaceable seam — belong to <code>Static()</code>, which has no instance dimension.</li><li><strong>Persistence, routing, and I/O stay themselves.</strong> The claim collapses the <em>state-architecture middle layer</em> — the five-category zoo between your data and your renderer — not your HTTP client.</li></ul><p>Inside that boundary, the reduction is total: if the thing holds reactive state, derives from it, or mutates it, it is a plain class with one transform applied, and its only design decision is its lifetime.</p><h2 id="one-kilobyte-because-one-idea" tabindex="-1">One kilobyte because one idea <a class="header-anchor" href="#one-kilobyte-because-one-idea" aria-label="Permalink to &quot;One kilobyte because one idea&quot;">​</a></h2><p>The engine is <a href="/blog/one-kilobyte-feature">1.1 kB</a> for the same reason the transformer outlived the zoo it replaced: removing categories removes machinery. No store plugin, no injection tokens, no emitter registry, no composable-context rules — one transform over one class shape, applied identically at every lifetime.</p><p>The paper&#39;s lesson was never that attention was powerful. It was that the specialized architectures were <strong>redundant</strong> — that one primitive, honestly scaled, covered what a zoo of them had been covering badly.</p><p>Your state management has been telling you the same thing. <code>Reactive()</code> is all you need.</p>',24)])])}const b=a(n,[["render",r]]);export{g as __pageData,b as default};
